/**
 * @file codegen_strings.c
 * @brief Emit checked string operations, character conversion, and substring
 * fast paths.
 */

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things more clear. Also try to split long files (300+) into smaller thematic ones, like optimizer was before"
// Changes: Group this implementation by responsibility.
#include "codegen_internal.h"

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Pass the function to builtin selection for static operand types.
// Thread value placement through this emitter.
// Recognize a fixed one-character substring without overflowing the
// index.
bool cg_single_character_substring(const IrInstruction* inst) {
  const IrOperand* args = inst->operands.call.args;
  return args[1].type == IR_OP_INT32 && args[2].type == IR_OP_INT32 &&
         args[1].value.int32_value >= 0 && args[2].value.int32_value > 0 &&
         args[1].value.int32_value == args[2].value.int32_value - 1;
}

void cg_print_string_builtin(Ctx* ctx,
                             FILE* out,
                             const CgPlacement* placement,
                             IrFunction* fn,
                             IrInstruction* inst) {
  (void)fn;
  switch (inst->operands.call.type) {
    case IR_FX_STR_LEN:
      if (inst->result == IR_INVALID_ID)
        break;
      fputs("STRLEN ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_nl(out);
      break;
    case IR_FX_TO_INT:
      if (inst->result == IR_INVALID_ID)
        break;
      fputs("FLOAT2INT ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_nl(out);
      break;
    case IR_FX_CHR:
      fputs("INT2CHAR ", out);
      if (inst->result == IR_INVALID_ID) {
        fputs("GF@$tmp1", out);
      } else {
        cg_print_value(out, placement, inst->result);
      }
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_nl(out);
      break;

      // AI generated by: Antigravity / Gemini 3.8 Flash
      // Prompt: "Inspect builtins.txt and rewrite IFJcode26 mockup functions
      // using our codegen helpers and fill the missing cases in
      // cg_print_builtin"
      // Changes: Rewrote built-in function mockups to codegen
      // switch-case statement.
      // AI generated by: Codex (GPT-6.2-sol)
      // Prompt: "Implement all"
      // Changes: Select WRITE directly from the source type.

    case IR_FX_ORD:
      if (inst->result == IR_INVALID_ID)
        break;
      fputs("STRLEN GF@$tmp1 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_nl(out);
      // idx < 0 -> oob
      fputs("LT ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      fputs(" int@0", out);
      cg_print_nl(out);
      fprintf(out, "JUMPIFEQ $cg_ord_oob_%zu ", ctx->cg_state.builtin_label_id);
      cg_print_value(out, placement, inst->result);
      fputs(" bool@true", out);
      cg_print_nl(out);
      // idx < len -> if false (idx >= len) -> oob
      fputs("LT ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      fputs(" GF@$tmp1", out);
      cg_print_nl(out);
      fprintf(out, "JUMPIFNEQ $cg_ord_oob_%zu ",
              ctx->cg_state.builtin_label_id);
      cg_print_value(out, placement, inst->result);
      fputs(" bool@true", out);
      cg_print_nl(out);
      // in bounds: STRI2INT LF@res <str> <idx>
      fputs("STRI2INT ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      cg_print_nl(out);
      fprintf(out, "JUMP $cg_ord_end_%zu\n", ctx->cg_state.builtin_label_id);
      // oob: -1
      fprintf(out, "LABEL $cg_ord_oob_%zu\n", ctx->cg_state.builtin_label_id);
      fputs("MOVE ", out);
      cg_print_value(out, placement, inst->result);
      fputs(" int@-1", out);
      cg_print_nl(out);
      fprintf(out, "LABEL $cg_ord_end_%zu\n", ctx->cg_state.builtin_label_id);
      break;

    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Use a single bounds check and GETCHAR for a one-character
    // substring.
    case IR_FX_STR_SUB:
      if (cg_single_character_substring(inst)) {
        size_t label = ctx->cg_state.builtin_label_id;
        fputs("STRLEN GF@$tmp1 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        fputs("\nGT GF@$tmp1 GF@$tmp1 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[1]);
        fprintf(out,
                "\nJUMPIFEQ $cg_sub_char_%zu GF@$tmp1 bool@true\n"
                "EXIT int@40\nLABEL $cg_sub_char_%zu\n",
                label, label);
        if (inst->result != IR_INVALID_ID) {
          fputs("GETCHAR ", out);
          cg_print_value(out, placement, inst->result);
          cg_print_ws(out);
          cg_print_operand(out, placement, &inst->operands.call.args[0]);
          cg_print_ws(out);
          cg_print_operand(out, placement, &inst->operands.call.args[1]);
          cg_print_nl(out);
        }
        break;
      }
      fputs("STRLEN GF@$tmp1 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[0]);
      cg_print_nl(out);
      // 1. start < 0
      fputs("LT GF@$tmp2 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      fputs(" int@0", out);
      cg_print_nl(out);
      fprintf(out, "JUMPIFEQ $cg_sub_err_%zu GF@$tmp2 bool@true\n",
              ctx->cg_state.builtin_label_id);
      // 2. end < 0
      fputs("LT GF@$tmp2 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[2]);
      fputs(" int@0", out);
      cg_print_nl(out);
      fprintf(out, "JUMPIFEQ $cg_sub_err_%zu GF@$tmp2 bool@true\n",
              ctx->cg_state.builtin_label_id);
      // 3. start > end
      fputs("LT GF@$tmp2 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[2]);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      cg_print_nl(out);
      fprintf(out, "JUMPIFEQ $cg_sub_err_%zu GF@$tmp2 bool@true\n",
              ctx->cg_state.builtin_label_id);
      // 4. start >= len
      fputs("LT GF@$tmp2 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[1]);
      fputs(" GF@$tmp1", out);
      cg_print_nl(out);
      fprintf(out, "JUMPIFNEQ $cg_sub_err_%zu GF@$tmp2 bool@true\n",
              ctx->cg_state.builtin_label_id);
      // 5. end > len
      fputs("LT GF@$tmp2 GF@$tmp1 ", out);
      cg_print_operand(out, placement, &inst->operands.call.args[2]);
      cg_print_nl(out);
      fprintf(out, "JUMPIFEQ $cg_sub_err_%zu GF@$tmp2 bool@true\n",
              ctx->cg_state.builtin_label_id);
      if (inst->result == IR_INVALID_ID) {
        fprintf(out, "JUMP $cg_sub_end_%zu\n", ctx->cg_state.builtin_label_id);
      } else {
        // empty string init
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(" string@", out);
        cg_print_nl(out);
        // i = start (reuses GF@$tmp1)
        fputs("MOVE GF@$tmp1 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[1]);
        cg_print_nl(out);
        // while (i < end)
        fprintf(out, "LABEL $cg_sub_loop_%zu\n",
                ctx->cg_state.builtin_label_id);
        fputs("LT GF@$tmp2 GF@$tmp1 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[2]);
        cg_print_nl(out);
        fprintf(out, "JUMPIFNEQ $cg_sub_end_%zu GF@$tmp2 bool@true\n",
                ctx->cg_state.builtin_label_id);
        fputs("GETCHAR GF@$tmp3 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        fputs(" GF@$tmp1", out);
        cg_print_nl(out);
        fputs("CONCAT ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_value(out, placement, inst->result);
        fputs(" GF@$tmp3", out);
        cg_print_nl(out);
        fputs("ADD GF@$tmp1 GF@$tmp1 int@1\n", out);
        fprintf(out, "JUMP $cg_sub_loop_%zu\n", ctx->cg_state.builtin_label_id);
      }
      // err 40
      fprintf(out, "LABEL $cg_sub_err_%zu\n", ctx->cg_state.builtin_label_id);
      fputs("EXIT int@40\n", out);
      fprintf(out, "LABEL $cg_sub_end_%zu\n", ctx->cg_state.builtin_label_id);
      break;
    default:
      break;
  }
}
